create extension if not exists pgcrypto;
create table if not exists aios_organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table if not exists aios_departments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,name text not null);
create table if not exists aios_agents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,department_id uuid references aios_departments(id),agent_key text not null,name text not null,role text not null,status text not null default 'idle',primary_model text,trust_score numeric(5,2) default 0,authority jsonb not null default '{}'::jsonb,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(organization_id,agent_key));
create table if not exists aios_projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,name text not null,status text not null default 'active',created_at timestamptz not null default now());
create table if not exists aios_tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,project_id uuid references aios_projects(id),assigned_agent_id uuid references aios_agents(id),parent_task_id uuid references aios_tasks(id),title text not null,instructions text,status text not null default 'queued',risk_level text not null default 'low',result jsonb,created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz);
create table if not exists aios_memory(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,agent_id uuid references aios_agents(id),scope text not null default 'agent',content text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists aios_approvals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,agent_id uuid references aios_agents(id),task_id uuid references aios_tasks(id),action text not null,risk_level text not null,resource text,reason text,status text not null default 'pending',reviewed_by uuid,created_at timestamptz not null default now(),reviewed_at timestamptz);
create table if not exists aios_model_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,agent_id uuid references aios_agents(id),task_id uuid references aios_tasks(id),provider text not null,model text not null,input_tokens integer default 0,output_tokens integer default 0,latency_ms integer,cost_usd numeric(12,6) default 0,outcome text,created_at timestamptz not null default now());
create table if not exists aios_audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,agent_id uuid references aios_agents(id),task_id uuid references aios_tasks(id),event_type text not null,risk_level text not null default 'low',action text,decision text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists idx_aios_tasks_agent_status on aios_tasks(assigned_agent_id,status);
create index if not exists idx_aios_runs_agent_created on aios_model_runs(agent_id,created_at desc);
create index if not exists idx_aios_audit_org_created on aios_audit_events(organization_id,created_at desc);
